#include "p4pc/texture_key.h"
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define CHECK(x) do { if (!(x)) { fprintf(stderr,"texture_key:%d: %s\n",__LINE__,#x); return 1; } } while (0)
int main(void)
{
    /* Expected values from Python hashlib over explicit LE header + byte patterns,
     * not generated by the implementation under test. Covers both SHA tail cases. */
    static const struct {
        uint32_t w,h,format,entries,palette_format;
        const char *hex;
    } cases[]={
        {1,1,5,0,0,"4864112a91f7ca41ea996cd33570311dec3f85514cebf20c838ec8b908a48acd"},
        {17,3,5,0,0,"436f12e348b7a30ef0e50ec81af9e26ce0d9a716d05373a1bd73bf7aca91c8c0"},
        {3,2,8,16,1,"69fab6b3f19f05e4f0d8a896d966939e3dffdb383b20b9b93cb8afea7ebc0e46"},
        {3,2,9,256,1,"da3f6fb27e2d288bf59fc918a6623ee11d9ccde7222407787f57dd162db14ba1"},
        {3,2,9,256,2,"3687b8096a5a6a53941c143222d812952beef984a6c3a623ed5cb7ffe4046e31"}
    };
    uint8_t image[17*3*4], palette[256*4], copy[sizeof image];
    char hex[65], other[65];
    P4TexturePixels p={1,1,5,0,0,image,NULL};
    for (size_t i=0;i<sizeof image;++i) image[i]=(uint8_t)(i*37u+11u);
    for (size_t i=0;i<sizeof palette;++i) palette[i]=(uint8_t)(i*13u+7u);
    memcpy(copy,image,sizeof image);
    for (size_t i=0;i<sizeof cases/sizeof *cases;++i) {
        p.width=cases[i].w; p.height=cases[i].h; p.format=cases[i].format;
        p.palette_format=cases[i].palette_format; p.palette_entries=cases[i].entries;
        p.palette=cases[i].entries?palette:NULL;
        CHECK(p4_texture_key(&p,hex)==0);
        CHECK(strcmp(hex,cases[i].hex)==0);
        CHECK(memcmp(copy,image,sizeof image)==0);
        p.rgba=copy;
        CHECK(p4_texture_key(&p,other)==0 && strcmp(hex,other)==0);
        p.rgba=image;
    }
    /* Even a currently unused palette slot is part of public identity. */
    CHECK(p4_texture_key(&p,hex)==0);
    palette[1023]^=1;
    CHECK(p4_texture_key(&p,other)==0 && strcmp(hex,other)!=0);
    p.width=0; CHECK(p4_texture_key(&p,hex)==-1); p.width=3;
    p.palette_entries=255; CHECK(p4_texture_key(&p,hex)==-1); p.palette_entries=256;
    p.palette=NULL; CHECK(p4_texture_key(&p,hex)==-1); p.palette=palette;
    p.palette_format=0; CHECK(p4_texture_key(&p,hex)==-1); p.palette_format=1;
    p.format=5; CHECK(p4_texture_key(&p,hex)==-1); p.palette_entries=0; p.palette_format=0;
    CHECK(p4_texture_key(&p,hex)==0);
    p.width=UINT32_MAX; p.height=UINT32_MAX;
    CHECK(p4_texture_key(&p,hex)==-1);
    CHECK(p4_texture_key(NULL,hex)==-1);
    CHECK(p4_texture_key(&p,NULL)==-1);
    puts("texture_key: canonical direct/paletted SHA-256 vectors and bounds passed");
    return 0;
}
